-- public.rpc_join(p_world uuid, p_name text, p_stone text)
-- Generated by scripts/snapshot-functions.mjs from the migrations. Do not edit.
CREATE OR REPLACE FUNCTION public.rpc_join(p_world uuid, p_name text DEFAULT NULL::text, p_stone text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare me uuid := auth.uid(); w world; p player; born boolean := false; v_look jsonb; v_was_away boolean := false;
        v_since timestamptz; v_away jsonb; v_sx double precision; v_sy double precision;
begin
  perform private.pace(auth.uid(), 'look');
  if me is null then raise exception 'not signed in'; end if;
  if p_stone is not null and not exists (select 1 from runestones() r where r.id = p_stone) then
    perform private.bad_request('rpc_join', 'p_stone: not a Runestone');
  end if;
  select * into w from world where id = p_world;
  if not found then raise exception 'no such island'; end if;
  if not w.ready then raise exception 'that island is still being laid down'; end if;
  perform private.note_ip(me);
  select a.look into v_look from account a where a.uid = me;
  -- Player text: a name that reads as a keeper or staff is not taken (`private.name_refusal`).
  p_name := private.clean_text(p_name, 20);
  if private.name_refusal(p_world, me, p_name) is not null then p_name := null; end if;

  select * into p from player where world_id = p_world and uid = me;
  if not found then
    perform private.ip_body_take(p_world, me);
    select l.x + 0.5, l.y + 0.5 into v_sx, v_sy from start_landing(p_world, p_stone) l where p_stone is not null;
    insert into player (world_id, uid, name, x, y, stats, look)
    values (p_world, me, coalesce(nullif(trim(p_name), ''), 'Wanderer'), coalesce(v_sx, w.spawn_x + 0.5), coalesce(v_sy, w.spawn_y + 0.5),
            '{"health":1,"stamina":1,"hunger":1,"thirst":1}'::jsonb,
            look_clean(coalesce(v_look, look_random())))
    returning * into p;
    born := true;
    perform starter_kit(p_world, me);
    perform tell(p_world, me, 'You wash ashore on an untouched island with a few tools and your wits.', 'system');
  else
    if kit_topup(p_world, me) > 0 then
      perform tell(p_world, me, 'Starting kit: missing tools given.', 'system');
    end if;
    v_was_away := p.away;
    v_since := coalesce(p.left_at, p.seen_at);
    select jsonb_agg(jsonb_build_object('what', t.what, 'def', t.def, 'n', t.n, 'silver', t.silver)
                     order by t.what, t.n desc, t.def)
      into v_away from away_tally t where t.world_id = p_world and t.uid = me;
    delete from away_tally where world_id = p_world and uid = me;
    -- Asleep in a bed: woken beside it, with the sleep bonus of the time asleep (`private.sleep_wake`).
    perform private.sleep_wake(p_world, me);
    update player set seen_at = now(), away = false, left_at = null,
           name = coalesce(nullif(trim(p_name), ''), name),
           look = look_clean(coalesce(v_look, nullif(player.look, '{}'::jsonb), look_random()))
      where world_id = p_world and uid = me returning * into p;
    perform tell(p_world, me,
      case when v_was_away then 'You come back to the island. Whatever you were doing has long since stopped.'
           else 'Resumed where you left off.' end, 'system');
  end if;

  return jsonb_build_object(
    'world', to_jsonb(w) - 'made_by',
    'you', to_jsonb(p),
    'new', born,
    'time', world_time(p_world),
    -- Land, lines and the pack come as Broadcast messages from this island.
    'hears', true,
    -- Every job says how it ended: the beat counts lines from here, rather than from its own first answer.
    'saidTo', (select coalesce(max(e.n), 0) from event e where e.world_id = p_world),
    -- What happened to your things while you were away, and for how long you were.
    'away', case when v_away is not null then jsonb_build_object(
      'secs', greatest(0, extract(epoch from now() - v_since))::bigint, 'tally', v_away) end);
end $function$
